source='''from collections import deque, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    tiles = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            perimeter=[]
            for y,x in cells:
                if y in (r0,r1) or x in (c0,c1): perimeter.append(grid[y][x])
            from collections import Counter
            frame=Counter(perimeter).most_common(1)[0][0]
            colors={grid[y][x] for y,x in cells if grid[y][x] != frame}
            if len(colors) != 1:
                continue
            color=next(iter(colors))
            mr=[y for y,x in cells if grid[y][x]==color]
            mc=[x for y,x in cells if grid[y][x]==color]
            tiles.append(dict(r0=r0,r1=r1,c0=c0,c1=c1,color=color, mr=(min(mr),max(mr)), mc=(min(mc),max(mc))))
    out=[row[:] for row in grid]
    rows=defaultdict(list); cols=defaultdict(list)
    for t in tiles:
        rows[(t['r0'],t['r1'])].append(t)
        cols[(t['c0'],t['c1'])].append(t)
    for group in rows.values():
        group.sort(key=lambda t:t['c0'])
        for i,a in enumerate(group):
            for b in group[i+1:]:
                if a['color'] != b['color']: continue
                lo=max(a['mr'][0],b['mr'][0]); hi=min(a['mr'][1],b['mr'][1])
                for y in range(lo,hi+1):
                    for x in range(a['c1']+1,b['c0']): out[y][x]=a['color']
                break
    for group in cols.values():
        group.sort(key=lambda t:t['r0'])
        for i,a in enumerate(group):
            for b in group[i+1:]:
                if a['color'] != b['color']: continue
                lo=max(a['mc'][0],b['mc'][0]); hi=min(a['mc'][1],b['mc'][1])
                for x in range(lo,hi+1):
                    for y in range(a['r1']+1,b['r0']): out[y][x]=a['color']
                break
    return out
'''
